const raw = $input.first().json;
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') { data = rawBody; }
}

function sanitize(s) { return String(s || '').substring(0, 10000); }

const userRequest = sanitize(data.userRequest || data.prompt || data.description || data.request || '');
const arch        = data.architecture || {};
const stack       = arch.stack        || 'Node.js/Express';
const mvpScope    = arch.mvp_scope    || userRequest.substring(0, 100);
const endpoints   = arch.priority_endpoints || [];
const dataModel   = arch.data_model   || {};
const stores      = arch.stores       || {};
const deployUrl   = data.deploy_url   || null;

// Priorité : project_name de l'Architect > extraction depuis mvp_scope
const rawProjectName = arch.project_name || data.project_name || '';
let projectName = '';
if (rawProjectName && rawProjectName.length > 1) {
  projectName = rawProjectName.trim();
} else if (mvpScope) {
  // Extraire nom depuis mvp_scope en supprimant les mots génériques
  projectName = mvpScope
    .replace(/^cr[eéè]er\s+(une?\s+)?/i, '')
    .replace(/^(une?|le|la|les)\s+/i, '')
    .split(' ').slice(0, 3).join(' ')
    .trim();
  projectName = projectName.charAt(0).toUpperCase() + projectName.slice(1);
}
if (!projectName || projectName.length < 2) projectName = 'Application';

if (!data.task_id) {
  return [{ json: { error_code: "VALIDATION_ERROR", error_message: "task_id manquant", timestamp: new Date().toISOString() } }];
}
if (!userRequest) {
  return [{ json: { error_code: "VALIDATION_ERROR", error_message: "userRequest manquant", timestamp: new Date().toISOString() } }];
}

// Construire contexte API
let apiDocs = '';
if (endpoints.length > 0) {
  apiDocs = '\n\nENDPOINTS API :\n';
  endpoints.forEach(ep => { apiDocs += '- ' + ep.method + ' ' + ep.path + ' : ' + (ep.description || '') + '\n'; });
}

// Champs requis par ressource
let storeDocs = '';
if (Object.keys(stores).length > 0) {
  storeDocs = '\n\nCHAMPS REQUIS PAR RESSOURCE :\n';
  Object.keys(stores).forEach(res => {
    const cfg = stores[res];
    storeDocs += '- POST /' + cfg.store_name + ' : ' + (cfg.required_fields || []).join(', ') + '\n';
  });
}

// Exemples curl
let curlExamples = '';
endpoints.forEach(ep => {
  if (ep.path === '/health') {
    curlExamples += 'curl http://localhost:3000/health\n';
  } else if (ep.method === 'GET') {
    curlExamples += 'curl http://localhost:3000' + ep.path + '\n';
  } else if (ep.method === 'POST') {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    const resName = seg.replace(/s$/, '');
    const reqFields = stores[resName]?.required_fields || [];
    if (reqFields.length > 0) {
      const exBody = reqFields.reduce((acc, f) => {
        acc[f] = (dataModel[resName]?.[f] === 'number') ? 1 : 'exemple';
        return acc;
      }, {});
      curlExamples += 'curl -X POST http://localhost:3000' + ep.path + ' \\\n';
      curlExamples += '  -H "Content-Type: application/json" \\\n';
      curlExamples += '  -d \'' + JSON.stringify(exBody) + '\'\n';
    }
  }
  curlExamples += '\n';
});

const improvementPrompts = [
  'Ajoute un bouton Supprimer sur chaque element de la liste',
  'Affiche ' + (Object.values(stores)[0]?.required_fields?.[1] || 'le titre') + ' et ' + (Object.values(stores)[0]?.required_fields?.[2] || 'la description') + ' dans le titre de chaque item',
  'Ajoute un systeme de statut sur les reservations (en_attente, acceptee, refusee, livree)',
  'Ajoute une liste deroulante qui charge automatiquement les trajets disponibles dans le formulaire de reservation',
  'Ajoute la validation que tous les champs numeriques sont des nombres positifs'
];

const systemPrompt = `Tu es un expert en documentation technique.
REGLE ABSOLUE : Retourner UNIQUEMENT un objet JSON valide.

FORMAT :
{
  "agent": "documentation",
  "files": [
    { "path": "README.md", "content": "..." }
  ],
  "errors": []
}

STYLE (README de projet professionnel, rédigé par une équipe senior) :
- Français soigné, accents compris, phrases courtes, ton factuel. Aucun émoji, aucune formule creuse
  (« il est important de noter », « n'hésitez pas », « en résumé »), aucun superlatif.
- Ne JAMAIS mentionner de pipeline, de génération automatique, d'IA, d'agents ni de « prompts ».
- N'invente rien : seulement ce que décrivent les données fournies (routes, modèle, règles).

SECTIONS DU README, dans cet ordre :
1. Titre H1 = ${projectName} (exactement), puis une phrase qui dit ce que fait l'application et pour qui.
2. Fonctionnalités : liste concrète, une ligne par capacité réelle.
3. Démarrage rapide : prérequis (Node.js 18+), npm install, npm start (ou start.sh / start.bat), URL http://localhost:3000, création du premier compte.
4. Configuration : tableau des variables, EXACTEMENT celles du fichier .env.example fourni (nom, rôle, valeur par défaut). Base SQLite locale (better-sqlite3), données persistantes. N'invente AUCUNE autre variable (pas de DB_HOST, DB_USER…). Si PAYMENT_PROVIDER existe, expliquer le mode simulation et le passage à FedaPay (clé secrète en variable d'environnement, webhook POST /api/paiements/fedapay à déclarer dans le tableau de bord FedaPay).
5. Règles métier : reprendre fidèlement la liste RÈGLES MÉTIER fournie, en phrases lisibles ; mentionner les règles « à implémenter » s'il y en a.
6. API : authentification (POST /api/register, POST /api/login, POST /api/logout, GET /api/me ; session par cookie HttpOnly), puis un tableau Méthode | Route | Description pour les routes métier, et 3 exemples curl représentatifs.
7. Modèle de données : un tableau par ressource (champ, type, obligatoire).
8. Sécurité : mots de passe hachés (bcrypt), JWT en cookie HttpOnly, en-têtes de sécurité (helmet), limitation des tentatives, requêtes SQL paramétrées, journal d'audit, cloisonnement des données par utilisateur.
9. Tests : npm test, ce que vérifient les tests.
10. Limites connues : uniquement des limites réelles (ex. pas de réinitialisation de mot de passe par e-mail).

IMPORTANT : Le titre H1 DOIT etre exactement "${projectName}". Pas de variante.
Commence par { et termine par }.`;

const userPrompt = `Genere la documentation complete pour :

NOM DU PROJET (H1 obligatoire) : ${projectName}
STACK : ${stack}
TASK_ID : ${data.task_id}
${apiDocs}${storeDocs}

EXEMPLES CURL :
${curlExamples}

FICHIER .env.example :
${String(data.env_example || 'PORT=3000\nDB_PATH=./database.db\nNODE_ENV=development\nJWT_SECRET=').substring(0, 2000)}

RÈGLES MÉTIER (appliquées par le serveur) :
${String(data.rules_header || 'aucune règle particulière').substring(0, 4000)}

CONTEXTE :
${userRequest.substring(0, 2000)}

Retourne UNIQUEMENT le JSON.`;

return [{
  json: {
    task_id:      String(data.task_id),
    userRequest,
    systemPrompt,
    userPrompt
  }
}];

// ── Télémétrie LLM -> panel (crédits Tchavi, fournisseur, tokens) — ne bloque jamais ──
try {
  const _tr = ($input.first() || {}).json || {};
  if (_tr.choices) {
    const _tu = _tr.usage || {};
    const _tn = function (v) { return typeof v === 'number' ? v : (typeof v === 'string' && v.trim() !== '' && !isNaN(+v) ? +v : undefined); };
    const _tc = [_tr.credits_remaining, _tu.credits_remaining, _tr.tchavi && _tr.tchavi.credits_remaining,
                 _tr.billing && _tr.billing.credits_remaining, _tr.credits && _tr.credits.remaining].map(_tn).find(function (v) { return v !== undefined; });
    await this.helpers.httpRequest({
      method: 'POST', url: ($env.PANEL_TELEMETRY_URL || 'http://forge-panel:3001/telemetry'),
      body: { agent: 'documentation', model: _tr.model || null,
        provider: _tr.x_groq ? 'groq' : ((_tc !== undefined || /claude|gpt|^llama-3\.3-70b$/i.test(_tr.model || '')) ? 'tchavi' : 'fallback'),
        prompt_tokens: _tu.prompt_tokens || 0, completion_tokens: _tu.completion_tokens || 0, total_tokens: _tu.total_tokens || 0,
        credits_remaining: (_tc === undefined ? null : _tc), ts: Date.now() },
      json: true, timeout: 1500 });
  }
} catch (e) {}

const groqResponse = $input.first().json;
const upstream = $('Inject Prompt').first().json;

const raw = groqResponse.choices?.[0]?.message?.content;

if (!raw) {
  return [{
    json: {
      task_id: upstream.task_id,
      agent: "documentation", _version: '5.12',
      files: [],
      errors: [{ stage: "groq", message: "Réponse Groq vide" }]
    }
  }];
}

let parsed = {};
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  return [{
    json: {
      task_id: upstream.task_id,
      agent: "documentation", _version: '5.12',
      files: [],
      errors: [{ stage: "parsing", message: e.message }]
    }
  }];
}

const files = Array.isArray(parsed.files)
  ? parsed.files.filter(f => f.path && f.content !== undefined)
  : [];

return [{
  json: {
    task_id: upstream.task_id,
    agent: "documentation", _version: '5.12',
    files,
    errors: parsed.errors || []
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: false,
    agent: "Agent Documentation", _version: '5.12',
    task_id: "unknown",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;

return [{
  json: {
    model: "llama-3.3-70b",
    messages: [
      { role: "system", content: input.systemPrompt },
      { role: "user", content: input.userPrompt }
    ],
    temperature: 0,
    max_tokens: 8000
  }
}];

let input = $input.first().json;
// Réponse LLM inexploitable et aucun fichier : README de secours plutôt qu'un livrable sans documentation
if (!(Array.isArray(input.files) && input.files.length)) {
  try { const _fb = await (async () => {
// Fallback déterministe si les deux clés Groq échouent
// Génère un README minimal depuis les données déjà calculées dans Inject Prompt
const upstream = $('Inject Prompt').first().json;
const task_id = upstream.task_id || 'unknown';

// Extraire project_name depuis le systemPrompt
let projectName = 'Application';
const sysPrompt = upstream.systemPrompt || '';
const match = sysPrompt.match(/EXACTEMENT : ([^\n)]+)/);
if (match) projectName = match[1].trim();

const readme = '# ' + projectName + '\n\n' +

  '## Vue d\'ensemble\n\n' +
  'Application générée par le pipeline Forge IA.\n\n' +
  '## Installation\n\n' +
  '```bash\nnpm install\nnpm start\n```\n\n' +
  '## Configuration\n\n' +
  'Créer un fichier `.env` :\n```\nPORT=3000\n```\n\n' +
  '## Note\n\nDocumentation complète non générée (limite quota Groq). ' +
  'Relancer la génération demain pour obtenir le README complet.\n';

return [{
  json: {
    task_id,
    agent: 'documentation', _version: '5.12',
    files: [{ path: 'README.md', content: readme }],
    errors: [{ stage: 'groq_fallback', message: 'LLM indisponible (principal et secours) : README de secours généré.' }]
  }
}];
  })(); const _e = (input.errors || []).concat((_fb[0].json.errors || [])); input = Object.assign({}, _fb[0].json, { errors: _e.length ? _e : [{ message: 'Réponse du LLM inexploitable : README de secours généré.' }] }); } catch (e) {}
}
const hasFiles = Array.isArray(input.files) && input.files.length > 0;
const hasErrors = Array.isArray(input.errors) && input.errors.length > 0;
// README de secours (LLM indisponible ou illisible) : livrable utilisable mais dégradé => WARN, jamais PASS ni FAIL
const status = hasFiles && !hasErrors ? "PASS" : (hasFiles ? "WARN" : "FAIL");

return [{
  json: {
    success: status === 'PASS',
    agent: "Agent Documentation", _version: '5.12',
    task_id: input.task_id,
    status,
    global_score: status === 'PASS' ? 100 : (status === 'WARN' ? 50 : 0),
    degraded: status === 'WARN',
    approved_for_pipeline: status === 'PASS',
    language: "markdown",
    critical_issues: (hasErrors && !hasFiles)
      ? input.errors.map(e => ({ severity: "high", description: e.message || String(e) }))
      : [],
    degradation: (hasErrors && hasFiles) ? input.errors.map(e => e.message || String(e)) : [],
    warnings: [],
    recommendations: status === 'WARN'
      ? ["README de secours : relancer la génération pour la documentation complète"]
      : hasFiles
      ? ["Documentation générée avec succès"]
      : ["Régénérer — aucun fichier produit"],
    summary: hasFiles
      ? `${input.files.length} fichier(s) de documentation générés`
      : "Échec de génération documentation",
    dimensions: {
      security: { score: 100 },
      quality: { score: status === 'PASS' ? 100 : (status === 'WARN' ? 50 : 0) }
    },
    timestamp: new Date().toISOString(),
    files: input.files || []
  }
}];

// Fallback déterministe si les deux clés Groq échouent
// Génère un README minimal depuis les données déjà calculées dans Inject Prompt
const upstream = $('Inject Prompt').first().json;
const task_id = upstream.task_id || 'unknown';

// Extraire project_name depuis le systemPrompt
let projectName = 'Application';
const sysPrompt = upstream.systemPrompt || '';
const match = sysPrompt.match(/EXACTEMENT : ([^\n)]+)/);
if (match) projectName = match[1].trim();

const readme = '# ' + projectName + '\n\n' +

  '## Vue d\'ensemble\n\n' +
  'Application générée par le pipeline Forge IA.\n\n' +
  '## Installation\n\n' +
  '```bash\nnpm install\nnpm start\n```\n\n' +
  '## Configuration\n\n' +
  'Créer un fichier `.env` :\n```\nPORT=3000\n```\n\n' +
  '## Note\n\nDocumentation complète non générée (limite quota Groq). ' +
  'Relancer la génération demain pour obtenir le README complet.\n';

return [{
  json: {
    task_id,
    agent: 'documentation', _version: '5.12',
    files: [{ path: 'README.md', content: readme }],
    errors: [{ stage: 'groq_fallback', message: 'LLM indisponible (principal et secours) : README de secours généré.' }]
  }
}];

// Charge utile du failover (LLM gratuit, ex. Groq) — construite ici car $('…').first()
// ne se résout pas dans le body d'un httpRequest (règle R2). Le nœud HTTP envoie ={{ $json }}.
const src = $('Build Payload').first().json;
const out = { model: $env.FALLBACK_LLM_MODEL || 'llama-3.3-70b-versatile', messages: src.messages || [] };
if (typeof src.temperature === 'number') out.temperature = src.temperature;
if (typeof src.top_p === 'number') out.top_p = src.top_p;
// Les modèles gratuits plafonnent la sortie : on borne max_tokens pour éviter un 400
out.max_tokens = Math.min(Number(src.max_tokens) || 4096, Number($env.FALLBACK_LLM_MAX_TOKENS) || 8000);
return [{ json: out }];
